fn safe_divide(a: Float64, b: Float64) -> Result[Float64, Str] {
  if b == 0.0 {
    return Err("division by zero");
  }
  return Ok(a / b);
}

fn compute(a: Float64, b: Float64, c: Float64, d: Float64) -> Result[Float64, Str] {
  let first = safe_divide(a, b)?;
  let second = safe_divide(c, d)?;
  return Ok(first + second);
}

fn main() -> Int {
  let result = compute(10.0, 2.0, 6.0, 3.0);
  match result {
    Ok(val) => { return val as Int; }
    Err(msg) => { return 1; }
  }
}
